import{_ as n,o as i,c as e,a2 as a}from"./chunks/framework.BBd5PKnH.js";const g=JSON.parse('{"title":"Celestial condition in Traditional Astrology","description":"","frontmatter":{"title":"Celestial condition in Traditional Astrology","date":"2026-09-06T00:00:00.000Z"},"headers":[],"relativePath":"astro/note_4.md","filePath":"astro/note_4.md"}'),r={name:"astro/note_4.md"};function o(h,t,s,d,l,c){return i(),e("div",null,[...t[0]||(t[0]=[a('<h2 id="_1-mo-hinh-vu-tru-3-tang-cosmos" tabindex="-1">1. Mô hình vũ trụ 3 tầng (Cosmos) <a class="header-anchor" href="#_1-mo-hinh-vu-tru-3-tang-cosmos" aria-label="Permalink to &quot;1. Mô hình vũ trụ 3 tầng (Cosmos)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tầng</th><th>Yếu tố</th><th>Condition đánh giá</th></tr></thead><tbody><tr><td><strong>Fixed stars</strong></td><td>Decans, Zodiacal signs</td><td>Rulership systems, Sect rejoicing by sign</td></tr><tr><td><strong>Planetary spheres</strong></td><td>Solar phase (synodic cycle)</td><td>Speed, direction, visibility, phase; lunar applications/nodes/eclipses; aspects; bonification/maltreatment</td></tr><tr><td><strong>Earth</strong></td><td>Houses</td><td>Active/inactive houses, fortunate/unfortunate, joys of houses</td></tr></tbody></table><hr><h2 id="_2-celestial-condition-vs-terrestrial-disposition" tabindex="-1">2. Celestial Condition vs Terrestrial Disposition <a class="header-anchor" href="#_2-celestial-condition-vs-terrestrial-disposition" aria-label="Permalink to &quot;2. Celestial Condition vs Terrestrial Disposition&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Celestial Condition</th><th>Terrestrial Disposition</th></tr></thead><tbody><tr><td>Thời Trung Cổ gọi là</td><td>Essential dignity</td><td>Accidental dignity</td></tr><tr><td>Phụ thuộc vào</td><td>Sign, solar phase, aspect</td><td>House placement</td></tr><tr><td>Giống nhau cho người sinh cùng ngày?</td><td><strong>Có</strong> (trừ vị trí Moon)</td><td><strong>Không</strong> — tùy giờ/nơi sinh</td></tr></tbody></table><ul><li><strong>House không đổi được bản chất tốt/xấu của celestial condition</strong> — house chỉ quyết định <em>chủ đề nào</em> (tiền bạc, hôn nhân...) sẽ chịu ảnh hưởng đó.</li></ul><h2 id="_2b-planet-s-own-nature-vs-celestial-condition" tabindex="-1">2b. Planet&#39;s Own Nature vs Celestial Condition <a class="header-anchor" href="#_2b-planet-s-own-nature-vs-celestial-condition" aria-label="Permalink to &quot;2b. Planet&#39;s Own Nature vs Celestial Condition&quot;">​</a></h2><ul><li><strong>Own nature</strong> = bản chất <strong>cố định vĩnh viễn</strong> (Mars luôn malefic, Venus luôn benefic) — giống &quot;tính cách bẩm sinh&quot;</li><li><strong>Celestial condition</strong> = tình trạng <strong>thay đổi theo ngày</strong> (dignity, phase, aspect hôm đó) — giống &quot;hoàn cảnh sống hiện tại&quot;</li><li>Cả hai đều thuộc cõi trời (celestial), khác với house (terrestrial)</li></ul><hr><h2 id="_3-benefic-malefic" tabindex="-1">3. Benefic / Malefic <a class="header-anchor" href="#_3-benefic-malefic" aria-label="Permalink to &quot;3. Benefic / Malefic&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Benefic</th><th>Malefic</th><th>Trung tính</th></tr></thead><tbody><tr><td>Jupiter (greater), Venus (lesser)</td><td>Saturn (greater), Mars (lesser)</td><td>Sun, Moon, Mercury</td></tr></tbody></table><ul><li><strong>Sect</strong>: Jupiter = benefic phe ngày; Venus = benefic phe đêm; Saturn = malefic phe ngày (đỡ xấu hơn); Mars = malefic phe đêm (đỡ xấu hơn)</li><li><strong>Quan trọng:</strong> Malefic KHÔNG có nghĩa luôn xấu — nếu condition tốt + cùng sect → có thể mang lại địa vị/thành công lớn (nhưng thường đi kèm đấu tranh, khác với benefic mang lại thuận lợi dễ dàng)</li></ul><p><strong>Công thức:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Kết quả thực tế = Bản chất (benefic/malefic) × Celestial condition (tốt/xấu)</span></span></code></pre></div><hr><h2 id="_4-ba-yeu-to-cau-thanh-celestial-condition-theo-thu-tu-uu-tien" tabindex="-1">4. Ba yếu tố cấu thành Celestial Condition (theo thứ tự ưu tiên) <a class="header-anchor" href="#_4-ba-yeu-to-cau-thanh-celestial-condition-theo-thu-tu-uu-tien" aria-label="Permalink to &quot;4. Ba yếu tố cấu thành Celestial Condition (theo thứ tự ưu tiên)&quot;">​</a></h2><ol><li><strong>Zodiacal sign rulership</strong> (quan trọng nhất) — domicile, exaltation, triplicity, bound, decan</li><li><strong>Solar phase</strong> — quan hệ quỹ đạo với Mặt Trời: speed, direction, visibility, oriental/occidental, combust, heliacal rise/set</li><li><strong>Aspect configurations</strong> — quan hệ góc với hành tinh khác (trine/sextile tốt, square/opposition xấu)</li></ol><p>→ Đánh giá mang tính <strong>cộng dồn (cumulative)</strong>: càng nhiều yếu tố hỗ trợ → càng tốt; càng nhiều cản trở → càng xấu.</p><hr><h2 id="_5-bang-tieu-chi-tot-xau" tabindex="-1">5. Bảng tiêu chí Tốt / Xấu <a class="header-anchor" href="#_5-bang-tieu-chi-tot-xau" aria-label="Permalink to &quot;5. Bảng tiêu chí Tốt / Xấu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Yếu tố</th><th>Tốt</th><th>Xấu</th></tr></thead><tbody><tr><td>Dignity</td><td>Domicile, exaltation, triplicity</td><td>Detriment/exile, fall</td></tr><tr><td>Solar phase</td><td>Oriental, tự do (không combust)</td><td>Combust, under the beams</td></tr><tr><td>Speed/Direction</td><td>Direct, nhanh</td><td>Retrograde, station</td></tr><tr><td>Aspect với malefic</td><td>Không có square/opposition xấu</td><td>Bị square/opposition</td></tr><tr><td>Aspect với benefic</td><td>Nhận trine/sextile</td><td>Không nhận được</td></tr><tr><td>Sect</td><td>Cùng phe (in sect)</td><td>Nghịch phe (out of sect)</td></tr></tbody></table><p><strong>Retrograde</strong> = ảo giác quang học do khác biệt tốc độ quỹ đạo Trái Đất – hành tinh, không phải hành tinh thực sự đi lùi.</p><hr><h2 id="_6-peregrine" tabindex="-1">6. Peregrine <a class="header-anchor" href="#_6-peregrine" aria-label="Permalink to &quot;6. Peregrine&quot;">​</a></h2><ul><li>Hành tinh <strong>không có bất kỳ essential dignity nào</strong> (không domicile, không exaltation, không triplicity, không bound, không decan) tại vị trí nó đang đứng</li><li><strong>Ẩn dụ:</strong> như ở khách sạn tại nước ngoài — không bị ai &quot;ghét&quot; (khác exile/fall) nhưng cũng không ai hỗ trợ</li><li>Là <strong>trạng thái trung gian</strong> — kết quả sẽ tùy thêm vào aspect nhận được</li></ul><table tabindex="0"><thead><tr><th>Trạng thái</th><th>Ẩn dụ</th></tr></thead><tbody><tr><td>Domicile</td><td>Ở nhà mình</td></tr><tr><td>Exaltation</td><td>Nhà khách quý</td></tr><tr><td>Triplicity/Bound/Decan</td><td>Nhà họ hàng, bạn bè</td></tr><tr><td>Peregrine</td><td>Khách sạn nước ngoài, không quen ai</td></tr><tr><td>Detriment/Fall</td><td>Nhà kẻ thù</td></tr></tbody></table><hr><h2 id="_7-traditional-rulership-khac-modern" tabindex="-1">7. Traditional Rulership (khác Modern) <a class="header-anchor" href="#_7-traditional-rulership-khac-modern" aria-label="Permalink to &quot;7. Traditional Rulership (khác Modern)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hành tinh</th><th>Sign 1</th><th>Sign 2 (traditional)</th><th>Modern thay bằng</th></tr></thead><tbody><tr><td>Mars</td><td>Aries</td><td><strong>Scorpio</strong></td><td>Pluto</td></tr><tr><td>Jupiter</td><td>Sagittarius</td><td><strong>Pisces</strong></td><td>Neptune</td></tr><tr><td>Saturn</td><td>Capricorn</td><td><strong>Aquarius</strong></td><td>Uranus</td></tr></tbody></table><ul><li>Khi thực hành traditional astrology: <strong>luôn dùng ruler cổ điển</strong> (Mars/Jupiter/Saturn), không dùng Uranus/Neptune/Pluto — vì các hành tinh hiện đại không có dignity/sect/phase trong hệ Hellenistic.</li><li><strong>House ruler</strong>: sign nào nằm trên cusp house → hành tinh cai quản sign đó là &quot;ruler&quot; của house → celestial condition của hành tinh này quyết định chủ đề house đó tốt/xấu ra sao.</li></ul><p><strong>Ví dụ:</strong> Lá số Maria von Trapp — house 2 (tiền bạc) có sign Scorpio → ruler là Mars (không phải Pluto) → Mars ở domicile, cùng sect (đêm) → condition tốt → tài chính thuận lợi (khớp thực tế: kết hôn với nam tước giàu có qua nhà 7 - Aries cũng do Mars cai quản).</p><hr><h2 id="_8-khac-biet-traditional-vs-modern-astrology-cot-loi" tabindex="-1">8. Khác biệt Traditional vs Modern Astrology (cốt lõi) <a class="header-anchor" href="#_8-khac-biet-traditional-vs-modern-astrology-cot-loi" aria-label="Permalink to &quot;8. Khác biệt Traditional vs Modern Astrology (cốt lõi)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Modern</th><th>Traditional</th></tr></thead><tbody><tr><td>Mọi hành tinh ngang hàng về sức mạnh</td><td>Hành tinh mạnh/yếu khác nhau tùy condition</td></tr><tr><td>Diễn giải = trộn từ khóa (keywords)</td><td>Phải xác định <strong>condition trước</strong>, rồi mới áp dụng vào house</td></tr></tbody></table>',34)])])}const p=n(r,[["render",o]]);export{g as __pageData,p as default};
